const modules=[['IKR3013','Computer Hardware & Software',1,'Perkakasan komputer, sistem operasi, spesifikasi PC.','cpu ram motherboard windows'],['IKR3023','Network Structured Cabling',1,'Topologi, media kabel, patch panel dan simulasi rak server.','rj45 cat6 crimping kabel'],['IKR3033','Fiber Cabling',1,'Gentian optik, penyambung, fusion splicing, OTDR dan kuasa optik.','fiber optik'],['IKR3043','Computer Fundamental Network',1,'Asas rangkaian, topologi, alamat IP, subnetting, protokol dan keselamatan.','ip calculator troubleshooting'],['IKR3053','Wireless Technology',1,'Wireless access point, RF, channel, antena dan Wi-Fi.','wlan wifi'],['IKR3082','Network Documentation',1,'Dokumentasi, audit, senarai semak dan rajah rangkaian.','diagram'],['IKR3063','Ethernet Switching Essentials',2,'Switch, VLAN, inter-VLAN routing, STP dan port security.','switching trunk'],['IKR3073','Basic Routing Configuration',2,'Router, IOS, jadual penghalaan dan static routing.','router'],['IKR3093','Server Essentials',2,'Pelayan, mesin maya, hypervisor, RAID dan pengujian OS pelayan.','server virtualization'],['IKR3103','Network Operating System',2,'Linux, web server, DNS, DHCP dan directory server.','apache nginx openldap'],['IKR3113','Network Monitoring Services',2,'Pemantauan rangkaian, SNMP, NAS dan RAID.','nms storage'],['IKR3133','Network Security Essentials',2,'Konsep, dasar, peraturan dan konfigurasi firewall.','firewall security'],['IKR3122','Project Management',2,'Tinjauan tapak, WLAN, liputan isyarat dan lukisan rangkaian.','project'],['IKR3143','Network Security Hardening',3,'Pengukuhan keselamatan, dasar, audit dan peralatan rangkaian.','security hardening'],['IKR3153','Network Automation Services',3,'Python, Bash, Perl, Ansible, Chef, Puppet, Git dan skrip automasi.','automation'],['IKR3163','Network Maintenance',3,'IPv4, subnetting, VLSM, IPv6, ancaman siber dan hardening end node.','maintenance']];
