const models=[{title:'PC 3D',poster:assets.pc,glb:'gaming-pc.glb',parts:[['Semua komponen','Komputer ialah gabungan perkakasan yang bekerjasama untuk memproses maklumat.'],['Casing','Melindungi komponen dalaman komputer.'],['Motherboard','Papan utama yang menghubungkan komponen komputer.'],['CPU','Memproses arahan dan menjalankan pengiraan.'],['RAM','Menyimpan data sementara semasa komputer beroperasi.'],['Storage','Menyimpan fail dan sistem operasi.'],['Power Supply','Membekalkan kuasa kepada komponen.'],['Kad grafik','Memproses paparan grafik.']]},{title:'Rack Server 3D',poster:"data:image/webp;base64,",glb:'semester-1.glb',parts:[['Semua komponen','Rak menyusun peralatan pelayan dan rangkaian dengan teratur.'],['Rangka rack','Menyokong dan menempatkan peralatan rangkaian.'],['Pintu rack','Memberi akses kepada peralatan dan membantu melindunginya.'],['Panel kaca','Membolehkan peralatan dilihat tanpa membuka pintu.'],['Unit pelayan','Menjalankan perkhidmatan dan menyimpan atau memproses data.'],['Kabel rangkaian','Menghubungkan peranti untuk komunikasi data.'],['LED status','Memberi petunjuk status peralatan.']]}];
let liveEnabled=false;
function removeModel(){modelRequest++;if(model){model.remove();model=null}const img=$('#heroImage');if(img)img.style.visibility='visible'}
function showPart(){const m=models[slide];$('#partInfo').textContent=m.parts[Number($('#partSelect').value)||0][1]}
function setSlide(i){removeModel();slide=(i+2)%2;const m=models[slide];$('#viewerTitle').textContent=m.title+' · '+(slide+1)+' / 2';const img=$('#heroImage');img.src=m.poster;img.alt='Pratonton '+m.title;$('#previewLabel').textContent='Pratonton visual';$('#viewerStatus').textContent='Tekan kiri atau kanan untuk menukar model. Putaran 3D memerlukan internet.';$('#live3d').innerHTML=icons.box+' Cuba model 3D';$('#partSelect').replaceChildren(...m.parts.map(([name],i)=>new Option(name,String(i))));showPart();$$('.dot').forEach((d,j)=>d.setAttribute('aria-pressed',String(j===slide)));if(liveEnabled)loadCurrentModel()}
function loadModelViewer(){if(customElements.get('model-viewer'))return Promise.resolve();if(modelScript)return modelScript;modelScript=new Promise((resolve,reject)=>{const s=document.createElement('script');s.type='module';s.src='https://ajax.googleapis.com/ajax/libs/model-viewer/4.1.0/model-viewer.min.js';let timer=setTimeout(()=>{s.remove();reject(new Error('timeout'))},10000);s.onerror=()=>{clearTimeout(timer);s.remove();reject(new Error('network'))};customElements.whenDefined('model-viewer').then(()=>{clearTimeout(timer);resolve()});document.head.append(s)}).catch(e=>{modelScript=null;throw e});return modelScript}
async function loadCurrentModel(){const request=++modelRequest;const m=models[slide];$('#viewerStatus').textContent='Memuatkan '+m.title+'…';try{await loadModelViewer();if(request!==modelRequest)return;const active=document.createElement('model-viewer');model=active;active.setAttribute('src',SITE+'models/'+m.glb);active.setAttribute('alt',m.title);active.setAttribute('camera-controls','');active.setAttribute('touch-action','pan-y');active.setAttribute('interaction-prompt','none');active.setAttribute('camera-orbit','35deg 75deg auto');active.style.opacity='0';active.style.pointerEvents='none';let timeout=setTimeout(fail,16000);function fail(){clearTimeout(timeout);if(model!==active)return;removeModel();liveEnabled=false;$('#viewerStatus').textContent='Model 3D tidak dapat dimuatkan. Pratonton visual dikekalkan.'}active.addEventListener('error',fail,{once:true});active.addEventListener('load',()=>{clearTimeout(timeout);if(model!==active)return;active.style.opacity='1';active.style.pointerEvents='auto';$('#heroImage').style.visibility='hidden';$('#previewLabel').textContent='Model 3D';$('#viewerStatus').textContent='Seret untuk putar · Zum dengan roda tetikus atau dua jari.';$('#live3d').innerHTML=icons.box+' Pratonton asal'},{once:true});$('#stage').append(active)}catch{if(request===modelRequest){liveEnabled=false;$('#viewerStatus').textContent='Sambungan 3D tidak tersedia. Pratonton dikekalkan.'}}}
if($('#heroImage')){ $('#prev').onclick=()=>setSlide(slide-1);$('#next').onclick=()=>setSlide(slide+1);$$('.dot').forEach(d=>d.onclick=()=>setSlide(Number(d.dataset.slide)));$('#reset').onclick=()=>{const wasLive=liveEnabled;liveEnabled=false;setSlide(slide);if(wasLive){liveEnabled=true;loadCurrentModel()}};$('#partSelect').onchange=showPart;$('#live3d').onclick=()=>{if(liveEnabled){liveEnabled=false;setSlide(slide)}else{liveEnabled=true;loadCurrentModel()}};$('#stage').addEventListener('keydown',e=>{if(e.target.matches('button')&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();setSlide(slide+(e.key==='ArrowRight'?1:-1))}},{signal:abort.signal});setSlide(0);}
function showDialog(title){$('#dialogTitle').textContent=title;if(!dialog.open){dialogOpener=document.activeElement;dialog.showModal()}}$('#closeDialog').onclick=()=>dialog.close();dialog.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();dialog.close()}},{capture:true,signal:abort.signal});dialog.addEventListener('close',()=>{dialogOpener?.focus()},{signal:abort.signal});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}},{signal:abort.signal});
function displayResults(){const input=$('#query');context.query=input.value;const words=input.value.trim().toLowerCase().split(/\s+/).filter(Boolean);const matches=modules.filter(m=>(!context.sem||m[2]===context.sem)&&words.every(w=>m.join(' ').toLowerCase().includes(w)));$('#resultCount').textContent=matches.length+' modul dijumpai';const results=$('#results');results.replaceChildren();for(const m of matches){const b=document.createElement('button');b.className='result';b.type='button';b.innerHTML='<div><b>'+m[0]+' · '+m[1]+'</b><small>Semester '+m[2]+' · '+m[3]+'</small></div>'+icons.right;b.onclick=()=>{if(onModuleSelect){dialog.close();onModuleSelect(m[0],m[2]);}else moduleDetail(m)};results.append(b)}if(!matches.length){const p=document.createElement('p');p.textContent='Tiada padanan. Cuba kod modul atau kata kunci lain.';results.append(p)}}
function openSearch(sem=0,query=''){context={sem,query};showDialog(sem?'Semester '+sem+' — Senarai modul':'Cari modul');body.innerHTML='<p>'+ (sem?'Pilih modul untuk memulakan pembelajaran.':'Cari kod, nama atau kata kunci dalam 16 modul.')+'</p><label class="field">'+icons.search+'<input id="query" type="search" placeholder="Contoh: VLAN, firewall, IKR3013" aria-label="Cari modul"></label><p id="resultCount" role="status" style="margin-bottom:10px"></p><div class="results" id="results"></div>';$('#query').value=query;$('#query').addEventListener('input',displayResults);displayResults();$('#query').focus()}
function moduleDetail(m){showDialog('Maklumat modul');body.innerHTML='<div class="detailcode">'+m[0]+' · Semester '+m[2]+'</div><h3 class="detailtitle">'+m[1]+'</h3><p>'+m[3]+'</p><p style="margin-top:15px">Untuk membaca nota penuh atau menjawab kuiz, buka portal asal dan pilih kod modul ini. Prototaip ini tidak menggantikan kandungan pembelajaran sebenar.</p><div class="modalactions"><button class="btn outline" id="backResults">Kembali ke senarai</button><a class="btn" href="'+SITE+'">Buka portal asal '+icons.external+'</a></div>';$('#backResults').onclick=()=>openSearch(context.sem,context.query);$('#backResults').focus()}
$('#searchBtn').onclick=()=>openSearch();window.addEventListener('esl:open-lab-chooser',()=>root.querySelector('[data-chooser]')?.click(),{signal:abort.signal});$$('[data-sem]').forEach(b=>b.onclick=()=>openSearch(Number(b.dataset.sem)));document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch()}},{signal:abort.signal});$$('[data-chooser]').forEach(b=>b.onclick=()=>{showDialog('Pilih Makmal Interaktif');body.innerHTML='<p>Dua simulator amali, dibuka pada halaman masing-masing.</p><div class="labchoice">'+labs.map(l=>'<a class="choice" href="'+l.url+'"><img src="'+l.image+'" alt=""><b>'+l.title+'</b><small>'+l.desc+'</small><span>Buka makmal '+icons.external+'</span></a>').join('')+'</div>';body.querySelector('a').focus()});
const sections=['utama','semester','makmal','panduan'];function syncNav(){const y=window.scrollY+130;let id='utama';for(const s of sections){if((root.querySelector('#'+s)?.getBoundingClientRect().top+window.scrollY || 0)<=y)id=s}$$('.nav a').forEach(a=>{const active=a.hash==='#'+id;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})}window.addEventListener('scroll',syncNav,{passive:true,signal:abort.signal});syncNav();
const anchor=location.hash;const anchorTarget=anchor==='#pilih-makmal'?root.querySelector('#pilih-makmal'):anchor==='#pilih-semester'?root.querySelector('#semester'):null;if(anchorTarget)requestAnimationFrame(()=>{if(root.isConnected)anchorTarget.scrollIntoView({block:'start'})});


// V4.1 — review feedback: no network submission or hidden collection.
const feedbackForm=$('#feedbackForm');
if(feedbackForm){
 const feedbackMessage=$('#feedbackMessage'), status=$('#feedbackStatus'), output=$('#feedbackOutput'), exportBox=$('#feedbackExport');
 let prepared='';
 function invalidateFeedback(){prepared='';exportBox.hidden=true;output.value='';status.textContent='';$('#feedbackCounter').textContent=feedbackMessage.value.length+' / 1000';}
 feedbackForm.addEventListener('input',invalidateFeedback,{signal:abort.signal});
 feedbackForm.addEventListener('change',invalidateFeedback,{signal:abort.signal});
 feedbackForm.addEventListener('submit',e=>{e.preventDefault();if(!feedbackForm.reportValidity())return;const data=new FormData(feedbackForm);prepared=['Maklum balas eSL-IKR','Tarikh: '+new Date().toLocaleDateString('ms-MY'),'Kejelasan portal: '+data.get('rating')+'/5','Bahagian: '+data.get('category'),'Ulasan: '+(String(data.get('message')||'').trim()||'(Tiada ulasan)')].join('\n');output.value=prepared;exportBox.hidden=false;status.textContent='Maklum balas sedia untuk disalin atau dimuat turun. Belum dihantar kepada pasukan.';},{signal:abort.signal});
 $('#feedbackReset').addEventListener('click',()=>{feedbackForm.reset();invalidateFeedback();},{signal:abort.signal});
 $('#feedbackDownload').addEventListener('click',()=>{if(!prepared)return;const url=URL.createObjectURL(new Blob([prepared],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='Maklum-Balas-eSL-IKR.txt';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);status.textContent='Fail disediakan untuk dimuat turun. Kongsi fail tersebut dengan pasukan eSL-IKR.';},{signal:abort.signal});
 $('#feedbackCopy').addEventListener('click',async()=>{if(!prepared)return;try{await navigator.clipboard.writeText(prepared);status.textContent='Maklum balas disalin. Tampal dan kongsi dengan pasukan.';}catch{output.focus();output.select();status.textContent='Teks dipilih. Tekan Ctrl+C atau gunakan menu Salin pada telefon.';}},{signal:abort.signal});
}

return ()=>{abort.abort();if(dialog.open)dialog.close();removeModel();};
